                    <div
                      style={{
                        fontSize: 32,
                        fontWeight: 500,
                        color: mutedLight,
                        lineHeight: 1.4,
                      }}
                    >
                      {item.sub}
                    </div>
                  </div>
                </div>

                {i < flow.length - 1 && (
                  <div
                    style={{
                      width: 100,
                      flexShrink: 0,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <svg width="100" height="36" viewBox="0 0 100 36">
                      <line
                        x1="4"
                        y1="18"
                        x2={4 + 72 * lineProg}
                        y2="18"
                        stroke={accentLight}
                        strokeWidth="3"
                        strokeLinecap="round"
                        opacity={0.35}
                      />
                      <path
                        d="M78 10l14 8-14 8"
                        stroke={accentLight}
                        strokeWidth="3"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        fill="none"
                        opacity={lineProg * 0.55}
                      />
                    </svg>
                  </div>
                )}
              </React.Fragment>
            );
          })}
        </div>

        {/* Stats row */}
        <div style={{ display: "flex", gap: 56, width: "100%", justifyContent: "center" }}>
          {stats.map((stat, i) => {
            const sp = spring({
              frame,
              fps,
              delay: 95 + i * 16,
              config: { damping: 200 },
            });
            return (
              <div
                key={i}
                style={{
                  opacity: sp,
                  transform: `translateY(${interpolate(sp, [0, 1], [50, 0])}px)`,
                  flex: 1,
                  backgroundColor: "rgba(255, 255, 255, 0.04)",
                  borderRadius: 24,
                  border: "2px solid rgba(255, 255, 255, 0.08)",
                  padding: "44px 40px",
                  display: "flex",
                  alignItems: "center",
                  gap: 32,
                }}
              >
                <div style={{ fontSize: 60 }}>{stat.icon}</div>
                <div>
                  <div
                    style={{
                      fontSize: 80,
                      fontWeight: 800,
                      color: stat.color,
                      lineHeight: 1,
                    }}
                  >
                    {stat.value}
                  </div>
                  <div
                    style={{
                      fontSize: 34,
                      fontWeight: 600,
                      color: mutedLight,
                      marginTop: 6,
                    }}
                  >
                    {stat.label}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Bottom badge */}
        <SpringIn delay={130} direction="scale">
          <div
            style={{
              backgroundColor: "rgba(36, 109, 255, 0.08)",
              border: `2px solid ${accentMid}`,
              borderRadius: 24,
              padding: "30px 72px",
              display: "flex",
              alignItems: "center",
              gap: 24,
            }}
          >
            <div style={{ fontSize: 44 }}>🔁</div>
            <div
              style={{
                fontSize: 44,
                fontWeight: 700,
                color: accentLight,
                letterSpacing: "0.04em",
              }}
            >
              Manual process → fully automated, repeatable pipeline
            </div>
          </div>
        </SpringIn>
      </div>
    </AbsoluteFill>
  );
};

// ═══════════════════════════════════════════════════════════════════════════════
// BLACK TRANSITIONS
// ═══════════════════════════════════════════════════════════════════════════════
const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: darkest }} />
);

const FadeTransition: React.FC<{ inOut: "in" | "out"; durationFrames: number }> = ({
  inOut,
  durationFrames,
}) => {
  const frame = useCurrentFrame();
  const opacity =
    inOut === "in"
      ? interpolate(frame, [0, durationFrames], [1, 0], { extrapolateRight: "clamp" })
      : interpolate(frame, [0, durationFrames], [0, 1], { extrapolateRight: "clamp" });
  return (
    <AbsoluteFill
      style={{ backgroundColor: darkest, opacity, pointerEvents: "none" }}
    />
  );
};

