// Scene 1: 0–250 (10s)
// Scene 2: 250–500 (10s)
// Scene 3: 500–750 (10s)

const FADE_DUR = 18;

export default function InfluencerVettingVideo() {
  return (
    <AbsoluteFill style={{ backgroundColor: darkest, fontFamily: "sans-serif" }}>
      {/* Scene 1 */}
      <Sequence from={tc(0)} durationInFrames={tc(10)}>
        <SceneOne />
        <FadeTransition inOut="in" durationFrames={FADE_DUR} />
      </Sequence>

      {/* Fade out Scene 1 */}
      <Sequence from={tc(10) - FADE_DUR} durationInFrames={FADE_DUR}>
        <AbsoluteFill>
          <SceneOne />
          <FadeTransition inOut="out" durationFrames={FADE_DUR} />
        </AbsoluteFill>
      </Sequence>

      {/* Scene 2 */}
      <Sequence from={tc(10)} durationInFrames={tc(10)}>
        <SceneTwo />
        <FadeTransition inOut="in" durationFrames={FADE_DUR} />
      </Sequence>

      {/* Fade out Scene 2 */}
      <Sequence from={tc(20) - FADE_DUR} durationInFrames={FADE_DUR}>
        <AbsoluteFill>
          <SceneTwo />
          <FadeTransition inOut="out" durationFrames={FADE_DUR} />
        </AbsoluteFill>
      </Sequence>

      {/* Scene 3 */}
      <Sequence from={tc(20)} durationInFrames={tc(10)}>
        <SceneThree />
        <FadeTransition inOut="in" durationFrames={FADE_DUR} />
      </Sequence>

      {/* Fade out Scene 3 */}
      <Sequence from={tc(30) - FADE_DUR} durationInFrames={FADE_DUR}>
        <AbsoluteFill>
          <SceneThree />
          <FadeTransition inOut="out" durationFrames={FADE_DUR} />
        </AbsoluteFill>
      </Sequence>
    </AbsoluteFill>
  );
}
